'use strict';
function dragConnect(source,destination,success){
 let dragging=false,startX=0,startY=0,ghost=null;
 source.style.touchAction='none';source.ondragstart=e=>e.preventDefault();
 source.onpointerdown=e=>{if(source.disabled)return;startX=e.clientX;startY=e.clientY;dragging=true;source.setPointerCapture(e.pointerId)};
 source.onpointermove=e=>{if(!dragging||Math.hypot(e.clientX-startX,e.clientY-startY)<8)return;if(!ghost){ghost=source.cloneNode(true);ghost.removeAttribute('id');ghost.classList.add('dragGhost');$('dialog').append(ghost)}ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px'};
 const clean=()=>{dragging=false;ghost?.remove();ghost=null};
 source.onpointerup=e=>{if(!dragging)return;const moved=!!ghost,r=destination().getBoundingClientRect();clean();if(moved){source.addEventListener('click',e=>{if(e.isTrusted){e.preventDefault();e.stopImmediatePropagation()}},{once:true,capture:true});if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)success();else $('miniStatus').textContent='Drop the part on the marked target and try again.'}};
 source.onpointercancel=source.onlostpointercapture=clean;
}

function panelProcedure(){
 let angle=state.angle;
 const op=operation('power','manual','Surface solar array','Drag the slider to rotate the panel. Use the sunlight and estimated output to reach at least 98% alignment.',`<div class="solarScene"><span class="sunDisc">☀</span><div class="sunRays"></div><div id="solarArray"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="panelMast"></div><div class="lunarGround"></div></div><label>Alignment <input id="panelAngle" type="range" min="0" max="180" step="1" value="${angle}"></label><div class="instrument" id="panelReading"></div><button id="lockPanel">Check output</button>`,()=>angle);if(!op)return;
 const update=()=>{angle=Number($('panelAngle').value);const efficiency=Math.max(0,Math.cos((angle-optimum(state))*Math.PI/180));$('solarArray').style.transform=`rotate(${90-angle}deg)`;$('panelReading').textContent=`Panel ${angle}°  · Sun ${optimum(state)}° · Alignment ${Math.round(efficiency*100)}% · estimated output ${Math.round(45*efficiency*state.panelHealth/100)}  energy per day`;$('operationBench').style.setProperty('--sun-angle',(90-optimum(state))+'deg');return efficiency};
 $('panelAngle').oninput=update;update();$('lockPanel').onclick=()=>{if(update()<.98){op.status('Output is too low. Aim closer to the indicated solar elevation.');return}op.complete('Panel aligned. Output depends on panel condition. If enabled, automatic tracking still controls the angle.')};
}
function volatileProcedure(){
 const targetCell=(state.day*3+state.labProgress*5)%16;let scans=0,selected=-1;const scanned=new Set();
 const op=operation('science','volatiles','Ice and volatiles survey','Survey the crater and drill where the signal is strongest. Each sweep gives you six readings. You can reset without spending resources. Analyze your core to verify the simulated result.',`<div class="craterMap">${Array.from({length:16},(_,i)=>`<button data-probe="${i}" aria-label="Scan sector ${i+1}"><span>⌖</span><small>${i+1}</small></button>`).join('')}</div><div class="instrument" id="probeReading">RADAR · 0/6 readings</div><div class="buttons"><button id="resetSweep">New sweep</button><button id="drillSample" disabled>Drill selected sector</button><button id="analyzeCore" disabled>Analyze core</button></div><div id="coreSample" class="coreSample">SAMPLE TUBE · EMPTY</div>`);if(!op)return;
 const strength=i=>Math.max(10,100-25*(Math.abs(i%4-targetCell%4)+Math.abs(Math.floor(i/4)-Math.floor(targetCell/4))));
 document.querySelectorAll('[data-probe]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.probe);if(scans===6&&!scanned.has(i)){op.status('Six readings used. Select a scanned sector or start a new sweep.');return}if(!scanned.has(i)){scanned.add(i);scans++}selected=i;document.querySelectorAll('[data-probe]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));b.querySelector('span').textContent=strength(i)+'%';b.style.background=`rgba(85,190,220,${strength(i)/130})`;$('probeReading').textContent=`RADAR · ${scans}/6 · sector ${i+1} · strength ${strength(i)}%`;$('drillSample').disabled=false;$('analyzeCore').disabled=true;$('coreSample').textContent='SAMPLE TUBE · EMPTY'});
 $('resetSweep').onclick=()=>{scans=0;scanned.clear();selected=-1;document.querySelectorAll('[data-probe]').forEach(b=>{b.querySelector('span').textContent='⌖';b.style.background='';b.setAttribute('aria-pressed','false')});$('probeReading').textContent='RADAR · new sweep · 0/6';$('drillSample').disabled=$('analyzeCore').disabled=true;$('coreSample').textContent='SAMPLE TUBE · EMPTY'};
 $('drillSample').onclick=()=>{if(selected<0)return;if(strength(selected)<100){op.status('Weak evidence in this core. Follow stronger signals in nearby sectors.');$('coreSample').textContent='CORE · DRY REGOLITH';return}$('coreSample').innerHTML='<span>❄</span> CORE RECOVERED · POSSIBLE VOLATILES';$('analyzeCore').disabled=false;op.status('Sample collected. Analyze it to verify the simulated result.')};
 $('analyzeCore').onclick=()=>{if(selected!==targetCell)return;op.complete(`Analysis complete. +12 science and data. Research ${state.labProgress+1}/2; ${state.labProgress>=1?'improved water extraction unlocked':'one more analysis unlocks improved water extraction'}.`)};
}
// Technical procedures are local rehearsals; only the final commit changes the mission.
const previousOperationChoose=choose;
choose=function(key,id){const procedures={power:{battery:batteryProcedure,manual:panelProcedure},shield:{engine:engineProcedure},science:{soil:soilProcedure,volatiles:volatileProcedure},life:{repair:recyclerProcedure}};const run=procedures[key]?.[id];if(run)run();else previousOperationChoose(key,id)};
function operation(key,id,title,instructions,content,value=()=>undefined){
 const offer=options(state,key).find(o=>o.id===id);if(!offer?.enabled)return null;
 const mission=state,turn=state.day;let active=true,ready=false,committed=false;
 miniFrame(title,instructions,`<div class="opCost">COST ON CONFIRMATION · ${costs(offer)}</div><section class="workbench" id="operationBench"><header><span>AURORA / ${rooms.find(r=>r.key===key).label}</span><span id="opStage">PROCEDURE IN PROGRESS</span></header>${content}</section>`);
 $('operationBench').dataset.procedure=id;styleProcedure(id);
 $('modal').querySelector('.muted').textContent='Simplified training simulation. Use the mouse, touch, or Tab and Enter. Use arrow keys to adjust sliders.';
 $('dialog').scrollTop=0;
 const status=text=>{$('miniStatus').textContent=text};
 const complete=text=>{if(!active||ready)return;ready=true;$('opStage').textContent='CHECKS COMPLETE';$('operationBench').classList.add('verified');$('operationBench').querySelectorAll('button,input').forEach(el=>el.disabled=true);$('miniDone').disabled=false;$('miniDone').textContent='Confirm operation';status(text+' Confirm to apply the cost and result.');beep()};
 stopMini=()=>{active=false};
 $('miniDone').onclick=()=>{if(!active||!ready||committed)return;if(state!==mission||(!state.realtime&&state.day!==turn)||!options(state,key).find(o=>o.id===id)?.enabled){$('miniDone').disabled=true;status('Mission conditions changed or resources are low. Cancel and restart the procedure.');return}committed=true;active=false;$('miniDone').disabled=true;executeDecision(key,id,value())};
 return {status,complete};
}
function batteryProcedure(){
 const op=operation('power','battery','Connect the reserve battery','Drag the battery into the bay or press Insert Battery. Connect matching terminals by dragging cables or selecting terminals in pairs. Test continuity before enabling the battery.',`<div class="batteryBay"><button id="insertBattery" class="batteryPack"><span>▥</span>INSERT BATTERY<small>STORAGE · 35 UNITS</small></button><div class="batterySocket">AUXILIARY BAY<br><strong id="batteryMount">NOT CONNECTED</strong></div></div><div class="terminalGrid"><div><h3>BATTERY</h3><button data-source="plus" disabled>+ POSITIVE</button><button data-source="minus" disabled>− NEGATIVE</button></div><svg viewBox="0 0 180 120" aria-label="Connection cables"><path id="wirePlus" d="M5 28 C90 28 90 28 175 28"/><path id="wireMinus" d="M5 92 C90 92 90 92 175 92"/></svg><div><h3>RESERVE BUS</h3><button data-bus="plus" disabled>+ POSITIVE</button><button data-bus="minus" disabled>− NEGATIVE</button></div></div><div class="instrument"><span id="circuitReadout">Circuit isolated · 0/2 connections</span><button id="checkCircuit" disabled>Test continuity</button></div>`);if(!op)return;
 dragConnect($('insertBattery'),()=>document.querySelector('.batterySocket'),()=>{$('insertBattery').click();document.querySelector('.batterySocket').classList.add('docked')});
 document.querySelectorAll('[data-source]').forEach(b=>dragConnect(b,()=>document.querySelector(`[data-bus="${b.dataset.source}"]`),()=>{b.click();document.querySelector(`[data-bus="${b.dataset.source}"]`).click()}));
 let mounted=false,selected=null;const connected=new Set();
 $('insertBattery').onclick=()=>{mounted=true;$('insertBattery').disabled=true;$('batteryMount').textContent='MOUNTED · OFFLINE';document.querySelectorAll('[data-source],[data-bus]').forEach(b=>b.disabled=false);$('checkCircuit').disabled=false;op.status('Battery mounted. Connect the positive and negative terminals while the circuit is isolated.')};
 document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{selected=b.dataset.source;document.querySelectorAll('[data-source]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));op.status('Cable '+(selected==='plus'?'+':'−')+'  selected. Choose the matching bus terminal.')});
 document.querySelectorAll('[data-bus]').forEach(b=>b.onclick=()=>{if(!selected){op.status('Select a battery terminal first.');return}if(b.dataset.bus!==selected){op.status('Reversed polarity. The interlock blocked the connection. Select the matching terminal.');return}connected.add(selected);$('wire'+(selected==='plus'?'Plus':'Minus')).classList.add('connected');document.querySelector(`[data-source="${selected}"]`).classList.add('connected');b.classList.add('connected');$('circuitReadout').textContent=`Circuit isolated · ${connected.size}/2 connections`;op.status('Terminal '+(selected==='plus'?'+':'−')+' connected.');selected=null;document.querySelectorAll('[data-source]').forEach(x=>x.setAttribute('aria-pressed','false'))});
 $('checkCircuit').onclick=()=>{if(!mounted||connected.size!==2){op.status('Open circuit. Connect both terminals before enabling the battery.');return}$('circuitReadout').textContent='CONTINUITY OK · POLARITY OK · CHARGE 35';op.complete('Precharged battery ready. +35 energy and +35 reserve capacity. Surplus goes to the reserve.')};
}
function engineProcedure(){
 const fault=(state.day+state.engine/50)%3,goal=45+(state.day%3)*5;
 const op=operation('shield','engine','Repair the rescue engine','Inspect the three sections for a pressure drop. Replace the damaged seal, set both valves to the test pressure, then test ignition.',`<div class="engineDiagram"><div class="engineNozzle">THRUSTER<span class="exhaust"></span></div><div class="inspectionGrid">${['FEED','CHAMBER','RETURN'].map((name,i)=>`<button data-engine-part="${i}"><span>0${i+1} / ${name}</span><strong>INSPECT</strong></button>`).join('')}</div></div><div class="instrument" id="engineDiagnostic">Select a section to check its pressure.</div><button id="replaceSeal" disabled>Replace damaged seal</button><div class="valvePanel"><p>BENCH TEST · target <b>${goal} ±3</b> in both circuits · maximum difference 4</p>${['A','B'].map((name,i)=>`<label>Valve ${name}<input id="valve${name}" type="range" min="0" max="100" value="${i?80:20}" disabled><output id="pressure${name}">${i?80:20}</output></label>`).join('')}<div class="engineBalance" id="engineBalance">Replace the seal to unlock the test.</div><button id="testEngine" disabled>Run ignition test</button></div>`);if(!op)return;
 let selected=-1,repaired=false;
 document.querySelectorAll('[data-engine-part]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.enginePart);const bad=selected===fault&&!repaired;b.querySelector('strong').textContent=bad?'PRESSURE 32 → 12 ↓':'PRESSURE 32 → 32';b.classList.toggle('fault',bad);$('engineDiagnostic').textContent=bad?'Pressure drop found. Replace the damaged seal.':'This section holds pressure.';$('replaceSeal').disabled=!bad;op.status(bad?'Fault found. You can replace the seal.':'Inspect another section to find the leak.')});
 $('replaceSeal').onclick=()=>{if(selected!==fault)return;repaired=true;$('replaceSeal').disabled=true;document.querySelector(`[data-engine-part="${fault}"]`).classList.remove('fault');document.querySelector(`[data-engine-part="${fault}"] strong`).textContent='NEW SEAL · PRESSURE HELD';$('engineDiagnostic').textContent='Circuit sealed. Adjust the pressure before testing ignition.';['valveA','valveB','testEngine'].forEach(id=>$(id).disabled=false);updatePressure()};
 document.querySelectorAll('.valvePanel label').forEach((label,i)=>{const wheel=document.createElement('div');wheel.className='valveWheel';wheel.innerHTML='<span>✣</span><small>VALVE '+(i?'B':'A')+'</small>';label.before(wheel)});
 function updatePressure(){const a=Number($('valveA').value),b=Number($('valveB').value);$('pressureA').textContent=a;$('pressureB').textContent=b;document.querySelectorAll('.valveWheel span').forEach((w,i)=>w.style.transform=`rotate(${(i?b:a)*2.7}deg)`);const good=Math.abs(a-goal)<=3&&Math.abs(b-goal)<=3&&Math.abs(a-b)<=4;$('engineBalance').textContent=good?'PRESSURES BALANCED · READY TO TEST':`Difference ${Math.abs(a-b)} · adjust both circuits toward ${goal}`;$('engineBalance').classList.toggle('balanced',good);return good}
 $('valveA').oninput=$('valveB').oninput=updatePressure;
 $('testEngine').onclick=()=>{if(!repaired||!updatePressure()){op.status('Pressure outside tolerance. Adjust the valves and retry.');return}document.querySelector('.engineNozzle').classList.add('firing');$('engineDiagnostic').textContent='Test passed. Circuit sealed and ignition stable.';$('engineBalance').textContent='IGNITION VERIFIED · PRESSURES STABLE';op.complete(`Ignition stable. Engine condition will rise from ${state.engine}% to ${Math.min(100,state.engine+50)}%.`)};
}
function soilProcedure(){
 const patterns=[{name:'Basalt',bars:[80,25,35],shape:'◆'},{name:'Impact glass',bars:[25,80,35],shape:'✦'},{name:'Breccia',bars:[30,35,80],shape:'◈'}];
 const offset=(state.day+state.science/20|0)%12,sites=[offset,(offset+4)%12,(offset+8)%12],recorded=new Set();let selected=-1;
 const op=operation('science','soil','Analyze a lunar sample','Scan the tray with the pointer or Tab. Select a spot with a clear signal, compare its three channels with the references, and classify it. Record three spots.',`<div class="soilWorkbench"><div class="sampleTray">${Array.from({length:12},(_,i)=>`<button class="sampleCell" data-sample="${i}" aria-label="Scan spot ${i+1}"><span>${['◈','◆','✦'][i%3]}</span><small>${String(i+1).padStart(2,'0')}</small></button>`).join('')}</div><div class="spectrometer"><small>SCANNER / SIMULATED SIGNATURE</small><strong id="sampleReading">Scan a spot</strong><div class="spectrum">${[0,1,2].map(i=>`<div><i id="spectrum${i}" style="height:8%"></i><span>${'ABC'[i]}</span></div>`).join('')}</div><p id="sampleSelection">No reading selected</p></div></div><p class="opHint">Compare the simulated signatures with these training references.</p><div class="referenceGrid">${patterns.map((p,i)=>`<button data-classify="${i}" disabled><b>${p.shape} ${p.name}</b><span>Channels A / B / C</span><strong>${p.bars.join(' / ')}</strong></button>`).join('')}</div><div class="instrument" id="sampleCount">SCIENCE RECORD · 0/3 readings</div>`);if(!op)return;
 function inspect(i){const index=sites.indexOf(i),p=index<0?null:patterns[index];$('sampleReading').textContent=`Spot ${i+1} · ${recorded.has(i)?'recorded':p?'clear signal':'weak signal'}`;[0,1,2].forEach(c=>$('spectrum'+c).style.height=(p?p.bars[c]:[18,15,20][c])+'%')}
 document.querySelectorAll('[data-sample]').forEach(b=>{const i=Number(b.dataset.sample);b.onpointerenter=b.onfocus=()=>{if(!b.disabled&&selected<0)inspect(i)};b.onclick=()=>{selected=-1;document.querySelectorAll('[data-classify]').forEach(x=>x.disabled=true);document.querySelectorAll('[data-sample]').forEach(x=>x.setAttribute('aria-pressed','false'));inspect(i);if(recorded.has(i)){op.status('This spot is already recorded. Scan another.');return}if(!sites.includes(i)){selected=-1;document.querySelectorAll('[data-classify]').forEach(x=>x.disabled=true);$('sampleSelection').textContent='Weak signal. Select another spot.';op.status('Weak reading. Scan another spot on the tray.');return}selected=i;document.querySelectorAll('[data-sample]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('sampleSelection').textContent=`Spot ${i+1}  selected. Compare channels A, B and C.`;document.querySelectorAll('[data-classify]').forEach(x=>x.disabled=false)}});
 document.querySelectorAll('[data-classify]').forEach(b=>b.onclick=()=>{if(selected<0)return;const type=sites.indexOf(selected);if(Number(b.dataset.classify)!==type){op.status('Signature mismatch. Compare which channel has the strongest signal and retry.');return}recorded.add(selected);document.querySelector(`[data-sample="${selected}"]`).classList.add('sampleRecorded');document.querySelector(`[data-sample="${selected}"]`).setAttribute('aria-label',`Spot ${selected+1} recorded as ${patterns[type].name}`);selected=-1;document.querySelectorAll('[data-classify]').forEach(x=>x.disabled=true);document.querySelectorAll('[data-sample]').forEach(x=>x.setAttribute('aria-pressed','false'));$('sampleSelection').textContent='Reading recorded. Scan another spot.';$('sampleCount').textContent=`SCIENCE RECORD · ${recorded.size}/3 readings`;op.status('Classification recorded. Confirm the analysis to collect the data.');if(recorded.size===3){$('sampleSelection').textContent='Record complete. Ready to confirm.';op.complete('Three readings recorded. +20 science and +20 data to transmit to Earth.')}});
}
function recyclerProcedure(){
 const fault=state.day%3,ports=[[3,1],[3,1],[3,2],[3,1],[3,1],[0,3]],rotation=ports.map((_,i)=>1+(state.day+i)%3);let filterReady=false;
 const op=operation('life','repair','Restore the air recycler','Inspect the filters and replace the one with the largest pressure drop. Rotate all six ducts to route air from the top left inlet across the top row and back through the bottom row to the outlet.',`<div class="filterRack">${[0,1,2].map(i=>`<button data-filter="${i}">FILTER ${i+1}<strong>READ ΔP</strong></button>`).join('')}</div><p id="filterReading">A large pressure drop indicates a blockage.</p><button id="replaceFilter" disabled>Replace clogged filter</button><div class="airLoop"><aside><b>INLET →</b><b>← OUTLET</b></aside><div class="pipeGrid">${ports.map((_,i)=>`<button data-pipe="${i}" aria-label="Rotate duct ${i+1}" disabled><svg viewBox="0 0 100 100" aria-hidden="true"></svg><small>${i+1} · ROTATE ↻</small></button>`).join('')}</div></div><div class="instrument"><span id="airflowStatus">FLOW ISOLATED · CHECK FILTERS</span><button id="testAirflow" disabled>Test airflow</button></div>`);if(!op)return;
 let selected=-1;
 const directions=['up','right','down','left'];
 const connections=i=>ports[i].map(p=>(p+rotation[i])%4);
 function drawPipe(i){const b=document.querySelector(`[data-pipe="${i}"]`),ends=[[50,0],[100,50],[50,100],[0,50]],c=connections(i);b.querySelector('svg').innerHTML=`<path d="M${ends[c[0]].join(' ')} L50 50 L${ends[c[1]].join(' ')}"/><circle cx="50" cy="50" r="10"/>`;b.setAttribute('aria-label',`Duct ${i+1}: ${c.map(p=>directions[p]).join('  and')}. Rotate 90 degrees`)}
 ports.forEach((_,i)=>drawPipe(i));
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.filter);const bad=selected===fault&&!filterReady;b.querySelector('strong').textContent=bad?'ΔP 28 · CLOGGED':'ΔP 2 · CLEAR';$('filterReading').textContent=bad?'Clogged filter found. Replace it to restore airflow.':'Air flows through this filter.';$('replaceFilter').disabled=!bad});
 $('replaceFilter').onclick=()=>{if(selected!==fault)return;filterReady=true;$('replaceFilter').disabled=true;document.querySelector(`[data-filter="${fault}"] strong`).textContent='ΔP 2 · NEW FILTER';$('filterReading').textContent='Filter replaced. Reconnect the ducts and test airflow.';document.querySelectorAll('[data-pipe]').forEach(b=>b.disabled=false);$('testAirflow').disabled=false;$('airflowStatus').textContent='Rotate the ducts to complete the loop.'};
 document.querySelectorAll('[data-pipe]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.pipe);rotation[i]=(rotation[i]+1)%4;drawPipe(i);document.querySelectorAll('[data-pipe]').forEach(x=>x.classList.remove('flowing'));$('airflowStatus').textContent='Alignment changed. Test airflow again.'});
 $('testAirflow').onclick=()=>{if(!filterReady)return;document.querySelectorAll('[data-pipe]').forEach(x=>x.classList.remove('flowing'));let i=0,entry=3;const visited=new Set();while(!visited.has(i)){visited.add(i);const c=connections(i);if(!c.includes(entry))break;document.querySelector(`[data-pipe="${i}"]`).classList.add('flowing');const exit=c.find(p=>p!==entry);if(i===3&&exit===3&&visited.size===6){$('airflowStatus').textContent='FLOW RESTORED · 6/6 DUCTS';op.complete(`Air circulating. Efficiency ${state.efficiency}% → ${Math.min(100,state.efficiency+30)}%. Oxygen output depends on recycler mode and available energy.`);return}const row=Math.floor(i/3)+[ -1,0,1,0 ][exit],col=i%3+[0,1,0,-1][exit];if(row<0||row>1||col<0||col>2)break;i=row*3+col;entry=(exit+2)%4;}$('airflowStatus').textContent='OPEN LOOP · FOLLOW THE LIT PATH';op.status('Air cannot reach the outlet through all six ducts. Rotate the connection where the path breaks.')};
}
